BEGIN;\nCREATE EXTENSION IF NOT EXISTS pgcrypto;\n\nCREATE TABLE public.action_tokens (\n  token_hash text NOT NULL,\n  assignment_id text NOT NULL,\n  trip_id text NOT NULL,\n  driver_id text NOT NULL,\n  action text NOT NULL,\n  expires_at timestamp with time zone NOT NULL,\n  used_at timestamp with time zone,\n  created_at timestamp with time zone NOT NULL DEFAULT now()\n);\n\nCREATE TABLE public.dispatch_operations (\n  operation_key text NOT NULL,\n  trip_id text NOT NULL,\n  assignment_id text NOT NULL,\n  driver_id text NOT NULL,\n  action text NOT NULL,\n  status text NOT NULL DEFAULT 'processing'::text,\n  execution_id text NOT NULL,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  completed_at timestamp with time zone\n);\n\nALTER TABLE public.action_tokens ADD CONSTRAINT action_tokens_pkey PRIMARY KEY (token_hash);\n\nALTER TABLE public.dispatch_operations ADD CONSTRAINT dispatch_operations_pkey PRIMARY KEY (operation_key);\n\nCREATE UNIQUE INDEX one_processing_operation_per_trip ON public.dispatch_operations USING btree (trip_id) WHERE (status = 'processing'::text);\n\nALTER TABLE public.action_tokens ADD CONSTRAINT action_tokens_action_check CHECK ((action = ANY (ARRAY['PRANO'::text, 'REFUZO'::text, 'FILLIM'::text, 'PERFUNDIM'::text])));\n\nALTER TABLE public.action_tokens ADD CONSTRAINT action_tokens_action_not_null NOT NULL action;\n\nALTER TABLE public.action_tokens ADD CONSTRAINT action_tokens_assignment_id_not_null NOT NULL assignment_id;\n\nALTER TABLE public.action_tokens ADD CONSTRAINT action_tokens_created_at_not_null NOT NULL created_at;\n\nALTER TABLE public.action_tokens ADD CONSTRAINT action_tokens_driver_id_not_null NOT NULL driver_id;\n\nALTER TABLE public.action_tokens ADD CONSTRAINT action_tokens_expires_at_not_null NOT NULL expires_at;\n\nALTER TABLE public.action_tokens ADD CONSTRAINT action_tokens_token_hash_not_null NOT NULL token_hash;\n\nALTER TABLE public.action_tokens ADD CONSTRAINT action_tokens_trip_id_not_null NOT NULL trip_id;\n\nALTER TABLE public.dispatch_operations ADD CONSTRAINT dispatch_operations_action_check CHECK ((action = ANY (ARRAY['PRANO'::text, 'REFUZO'::text, 'FILLIM'::text, 'PERFUNDIM'::text])));\n\nALTER TABLE public.dispatch_operations ADD CONSTRAINT dispatch_operations_action_not_null NOT NULL action;\n\nALTER TABLE public.dispatch_operations ADD CONSTRAINT dispatch_operations_assignment_id_not_null NOT NULL assignment_id;\n\nALTER TABLE public.dispatch_operations ADD CONSTRAINT dispatch_operations_created_at_not_null NOT NULL created_at;\n\nALTER TABLE public.dispatch_operations ADD CONSTRAINT dispatch_operations_driver_id_not_null NOT NULL driver_id;\n\nALTER TABLE public.dispatch_operations ADD CONSTRAINT dispatch_operations_execution_id_not_null NOT NULL execution_id;\n\nALTER TABLE public.dispatch_operations ADD CONSTRAINT dispatch_operations_operation_key_not_null NOT NULL operation_key;\n\nALTER TABLE public.dispatch_operations ADD CONSTRAINT dispatch_operations_status_check CHECK ((status = ANY (ARRAY['processing'::text, 'completed'::text, 'failed'::text])));\n\nALTER TABLE public.dispatch_operations ADD CONSTRAINT dispatch_operations_status_not_null NOT NULL status;\n\nALTER TABLE public.dispatch_operations ADD CONSTRAINT dispatch_operations_trip_id_not_null NOT NULL trip_id;\n\nCOMMIT;
